import {
  booleanAttribute,
  ChangeDetectionStrategy,
  Component,
  HostBinding,
  Input,
  numberAttribute,
  OnChanges,
  SimpleChanges,
  ViewEncapsulation,
} from '@angular/core';
import { QIconComponent, QIconSize } from '@questrade/allspark-angular-components/icon';
import {
  QTooltipDirective,
  QTooltipPosition,
} from '@questrade/allspark-angular-components/tooltip';
import { QInteractiveIconColor } from './types/interactive-icon-color.type';
import { QInteractiveIconContext } from './types/interactive-icon-context.type';
import { QInteractiveIconSize } from './types/interactive-icon-size.type';
import { QLegacyInteractiveIconSize } from './types/legacy-interactive-icon-size.type';

@Component({
  imports: [QTooltipDirective, QIconComponent],
  selector: 'q-interactive-icon',
  templateUrl: './interactive-icon.component.html',
  styleUrls: ['./interactive-icon.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
})
export class QInteractiveIconComponent implements OnChanges {
  @Input() icon = '';
  @Input() context: QInteractiveIconContext = 'informative';
  @Input() size: QInteractiveIconSize = 'small';
  @Input() tooltipValue = '';
  @Input() tooltipPosition: QTooltipPosition = 'bottom';
  @Input({ transform: booleanAttribute }) disabled = false;
  @Input({ transform: numberAttribute }) tabindex = 0;
  @Input({ transform: numberAttribute }) tooltipShowDelay = 0;
  @Input({ transform: numberAttribute }) tooltipHideDelay = 0;
  @Input({ transform: numberAttribute }) tooltipLongPressDelay = 500;
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-interactive-icon';

  /**
   * @deprecated Use `size` api instead, To be removed.
   * @breaking-change First major after Apr 29, 2026
   */
  @Input() iconSize?: QLegacyInteractiveIconSize;

  /**
   * @deprecated Use `context` api instead, To be removed.
   * @breaking-change First major after Apr 29, 2026
   */
  @Input() get color(): QInteractiveIconColor {
    return this._color;
  }
  set color(value: QInteractiveIconColor) {
    this.context = this.COLOR_CONTEXT_MAPPING[value];
    this._color = value;
  }

  @HostBinding('class') _hostClassName = 'q-interactive-icon';

  protected iconNumericSize: QIconSize = '20';

  private _color: QInteractiveIconColor = 'grey';
  private readonly COLOR_CONTEXT_MAPPING: Record<QInteractiveIconColor, QInteractiveIconContext> = {
    grey: 'informative',
    green: 'success',
    red: 'danger',
    blue: 'info',
  };
  private readonly ICON_SIZE_MAPPING: Record<QInteractiveIconSize, QIconSize> = {
    small: '20',
    medium: '24',
  };
  private readonly LEGACY_ICON_SIZE_MAPPING: Record<QLegacyInteractiveIconSize, QIconSize> = {
    xxs: '12',
    xs: '16',
    sm: '20',
    md: '24',
    lg: '40',
  };

  ngOnChanges({ iconSize, size }: SimpleChanges): void {
    if (iconSize || size) {
      const legacy = this.iconSize;
      this.iconNumericSize = legacy
        ? this.LEGACY_ICON_SIZE_MAPPING[legacy]
        : this.ICON_SIZE_MAPPING[this.size];
    }
  }
}
